def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    MOD = 998244353
    dp = [[0] * (n + 1) for _ in range(n)]
    count = [0] * n

    for i in range(n):
        dp[i][1] = 1  # Each element is a subsequence of length 1
        count[0] += 1

    for length in range(2, n + 1):
        for i in range(n):
            for j in range(i):
                if (a[i] - a[j]) * (length - 1) % (i - j) == 0:
                    d = (a[i] - a[j]) // (length - 1)
                    if (a[j] + d) in a[j + 1:i]:
                        dp[i][length] += dp[j][length - 1]
                        dp[i][length] %= MOD
        count[length - 1] = sum(dp[i][length] for i in range(n)) % MOD

    return count
