    MOD = 10**9 + 7
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(i + 1):
            dp[i][j] = (dp[i - 1][j] * (i - j)) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD

    inversion_count = [0] * (n + 1)
    for end_index, inv_count in requirements:
        inversion_count[end_index] = inv_count

    result = 1
    for end_index in range(n):
        if inversion_count[end_index] > 0:
            result = (result * dp[end_index + 1][inversion_count[end_index]]) % MOD

    return result
