echo "def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    takahashi_cards.sort(reverse=True)
    aoki_cards.sort(reverse=True)
    table_cards.sort(reverse=True)

    turn = 0  # 0 for Takahashi, 1 for Aoki
    while True:
        if turn == 0:  # Takahashi's turn
            if not takahashi_cards:
                return 'Aoki'
            card_to_play = takahashi_cards.pop(0)
            # Try to take a card from the table
            for i in range(len(table_cards)):
                if table_cards[i] < card_to_play:
                    takahashi_cards.append(table_cards.pop(i))
                    break
        else:  # Aoki's turn
            if not aoki_cards:
                return 'Takahashi'
            card_to_play = aoki_cards.pop(0)
            # Try to take a card from the table
            for i in range(len(table_cards)):
                if table_cards[i] < card_to_play:
                    aoki_cards.append(table_cards.pop(i))
                    break
        turn = 1 - turn  # Switch turns
" > func.py

